namespace AskARabbiLIB.Grounding;

/// <summary>Localizes source-free navigation replies without a retrieval or generation round trip.</summary>
internal sealed record ConversationOpeningText(string Clarification, string Welcome, string OffTopic, string Title)
{
    internal static ConversationOpeningText ForLanguage(string? language) => ConversationPersonalization.NormalizeLanguage(language) switch
    {
        "French" => new("Quel sujet ou passage souhaitez-vous explorer ? Envoyez votre question ou une référence, et nous l'étudierons ensemble.", "Bienvenue ! Nous pouvons commencer par un court passage de la Torah, une pratique juive ou la paracha de la semaine. J'expliquerai le contexte et les termes nouveaux. Préférez-vous un récit ou une question ?", "Je me concentre sur les textes et les traditions juives, plutôt que sur les conseils mécaniques. Si votre question concerne la conduite pendant le Chabbat, précisez le contexte et nous examinerons les sources.", "Une question à explorer"),
        "German" => new("Welches Thema oder welche Textstelle möchten Sie besprechen? Senden Sie die Frage oder die Quellenangabe, dann gehen wir sie gemeinsam durch.", "Willkommen! Wir können mit einer kurzen Torastelle, einer jüdischen Praxis oder dem Wochenabschnitt beginnen. Ich erkläre den Kontext und unbekannte Begriffe. Möchten Sie mit einer Geschichte oder einer Frage anfangen?", "Mein Schwerpunkt liegt auf jüdischen Texten und Traditionen, nicht auf technischen Autotipps. Wenn Sie das Autofahren am Schabbat meinen, nennen Sie den Zusammenhang, dann betrachten wir die Quellen.", "Eine Frage zum Lernen"),
        "Hebrew" => new("איזה נושא או קטע תרצו ללמוד? שלחו את השאלה או את מראה המקום, ונעבור עליו יחד.", "ברוכים הבאים! אפשר להתחיל בקטע קצר מהתורה, בשאלה על מנהג יהודי או בפרשת השבוע. אסביר את הרקע ואת המונחים הלא מוכרים. תרצו להתחיל בסיפור או בשאלה?", "אני מתמקד בטקסטים ובמסורת היהודית, ולא בייעוץ מכני. אם הכוונה היא לנהיגה בשבת, הוסיפו את ההקשר ונבחן את המקורות.", "שאלה ללימוד"),
        "Italian" => new("Quale argomento o passo vuoi approfondire? Invia la domanda o il riferimento e lo studieremo insieme.", "Benvenuto! Possiamo iniziare con un breve passo della Torah, una pratica ebraica o la parashah della settimana. Spiegherò il contesto e i termini nuovi. Preferisci un racconto o una domanda?", "Mi concentro sui testi e sulle tradizioni ebraiche, non sui consigli meccanici. Se intendi la guida durante lo Shabbat, aggiungi il contesto e ne esamineremo le fonti.", "Una domanda da esplorare"),
        "Persian" => new("دوست دارید کدام موضوع یا بخش را بررسی کنیم؟ پرسش یا نشانی متن را بفرستید تا با هم آن را بخوانیم.", "خوش آمدید! می‌توانیم با بخشی کوتاه از تورات، یک رسم یهودی یا پاراشای هفته آغاز کنیم. زمینه و اصطلاحات ناآشنا را توضیح می‌دهم. داستان را ترجیح می‌دهید یا یک پرسش را؟", "تمرکز من بر متون و سنت‌های یهودی است، نه راهنمایی مکانیکی. اگر منظورتان رانندگی در شبات است، زمینهٔ پرسش را بگویید تا منابع را بررسی کنیم.", "پرسشی برای یادگیری"),
        "Polish" => new("Jaki temat lub fragment chcesz omówić? Podaj pytanie lub odnośnik, a przeanalizujemy go razem.", "Witaj! Możemy zacząć od krótkiego fragmentu Tory, żydowskiego zwyczaju lub paraszy na ten tydzień. Wyjaśnię kontekst i nowe pojęcia. Wolisz opowieść czy pytanie?", "Skupiam się na żydowskich tekstach i tradycjach, a nie na poradach mechanicznych. Jeśli chodzi o jazdę samochodem w Szabat, podaj kontekst, a przyjrzymy się źródłom.", "Pytanie do zgłębienia"),
        "Russian" => new("Какую тему или отрывок вы хотите обсудить? Пришлите вопрос или ссылку на текст, и мы разберём его вместе.", "Добро пожаловать! Можно начать с короткого отрывка Торы, еврейского обычая или недельной главы. Я объясню контекст и незнакомые термины. Предпочитаете рассказ или вопрос?", "Я занимаюсь еврейскими текстами и традициями, а не техническими советами об автомобилях. Если речь о вождении в Шаббат, уточните контекст, и мы рассмотрим источники.", "Вопрос для изучения"),
        "Spanish" => new("¿Qué tema o pasaje te gustaría explorar? Envía la pregunta o la referencia y lo estudiaremos juntos.", "¡Bienvenido! Podemos empezar con un pasaje breve de la Torá, una práctica judía o la parashá de la semana. Explicaré el contexto y los términos nuevos. ¿Prefieres un relato o una pregunta?", "Me centro en los textos y las tradiciones judías, no en consejos mecánicos. Si te refieres a conducir en Shabat, dime el contexto y examinaremos las fuentes.", "Una pregunta para explorar"),
        "Yiddish" => new("וועלכן ענין אָדער טעקסט ווילט איר לערנען? שיקט די פֿראַגע אָדער דעם מראה־מקום, און מיר וועלן עס דורכגיין צוזאַמען.", "ברוכים הבאים! מיר קענען אָנהייבן מיט אַ קורצן שטיקל תורה, אַ ייִדישן מנהג אָדער דער פּרשה פֿון דער וואָך. איך וועל דערקלערן דעם הינטערגרונט און אומבאַקאַנטע ווערטער. ווילט איר אָנהייבן מיט אַ מעשׂה אָדער אַ פֿראַגע?", "איך באַשעפֿטיק זיך מיט ייִדישע טעקסטן און מסורות, נישט מיט מעכאַנישע עצות. אויב איר מיינט פֿאָרן שבת, גיט צו דעם קאָנטעקסט און מיר וועלן באַטראַכטן די מקורות.", "אַ פֿראַגע צום לערנען"),
        _ => new("Which topic or passage would you like me to explain? Send the question or reference, and we can work through it together.", "Welcome! We can begin with a short Torah passage, a question about a Jewish practice, or this week's Torah portion. I'll introduce the context, explain unfamiliar terms, and read the sources with you.\n\nWould you prefer a story, a practical topic, or a first look at Genesis?", "I focus on Jewish texts, traditions, and practice rather than mechanical advice. If you mean how driving relates to Shabbat or another Jewish-law question, tell me the context and I'll explain it with sources.", "A question to explore"),
    };
}
